AUC_CMAP = LinearSegmentedColormap.from_list("auc", ["#F2EBCB", "#DE9B59", "#8B3F50"])
# Cover all existing model and measured-RNA split values; no position saturation.
STATE_NORM = Normalize(-0.25, 0.60, clip=False)
AUC_NORM = Normalize(0.20, 0.90, clip=False)

PATIENTS = list("ABCDEFGH")
METHODS = list(tls_patient[tls_patient.coefficient_set == "FULL_784"].groupby("method")["model_vs_RNA_local_r"].mean().sort_values(ascending=False).index)
