primary_artists = []

# ---------------------------------------------------------------------
# a | TLS: technical split realizations nested under held-out patients
# ---------------------------------------------------------------------
letter(fig, 0.014, 0.9811, "a")
fig.text(0.075, 0.9740, "TLS score and hotspot recovery", ha="left", va="top", fontsize=7.6, fontweight="bold")
fig.legend(handles=[
    Line2D([], [], marker='o', linestyle='none', markersize=2.0, color=NEUTRAL, label='Split'),
    Line2D([], [], color=INK, lw=.52, label='Primary'),
], loc='upper right', bbox_to_anchor=(.979, .9811), ncol=2, frameon=False,
    handlelength=1.0, handletextpad=.35, columnspacing=1.0, borderpad=0)

state_order = ["Measured RNA"] + METHODS

def nested_plate(pos, coef, split_metric, patient_metric, rna_split_metric, rna_patient_metric,
                 norm, cmap, title, show_methods):
    ax = fig.add_axes(pos)
    nrows = len(state_order)
    # header band and patient hierarchy
    for pj, p in enumerate(PATIENTS):
        title_bar(ax, pj, pj + 1, -0.72, 0.48, p, color=HEADER)
    # Keep a visible gutter between patient H and the attached mean rail at
    # final 180-mm width; otherwise the two headers read as one column.
    title_bar(ax, 8.18, 8.84, -0.72, 0.48, "Mean", color="#C9C8C3")
    # Same physical height as each cell: this ruler calibrates positions, not color.
    ax.text(9.80, -.48, 'Scale', ha='center', va='center', fontsize=7.0, color=INK)
    ax.plot([9.38, 9.38], [.14, .86], color=NEUTRAL, lw=.5)
    for value in (norm.vmin, norm.vmax):
        yp = .86 - norm(value) * .72
        ax.plot([9.28, 9.48], [yp, yp], color=NEUTRAL, lw=.5)
        ax.text(9.56, yp, f'{value:g}', ha='left', va='center', fontsize=7.0)

    for ri, row in enumerate(state_order):
        if ri % 2:
            ax.add_patch(Rectangle((0, ri), 8.84, 1, facecolor=STRIPE, edgecolor="none", zorder=0))
        if show_methods:
            ax.text(-0.15, ri + 0.5, row, ha="right", va="center", fontsize=7.0,
                    color=RNA if row == "Measured RNA" else INK,
                    fontweight="bold" if row == "Measured RNA" else "normal")
        primaries = []
        for pj, p in enumerate(PATIENTS):
            if row == "Measured RNA":
                raw = (tls_split[(tls_split.coefficient_set == coef) & (tls_split.heldout_patient == p)]
                       .drop_duplicates("split_index").sort_values("split_index")[rna_split_metric].to_numpy())
                primary = float(tls_patient[(tls_patient.coefficient_set == coef) & (tls_patient.heldout_patient == p)]
                                [rna_patient_metric].iloc[0])
            else:
                raw = (tls_split[(tls_split.coefficient_set == coef) & (tls_split.heldout_patient == p) & (tls_split.method == row)]
                       .sort_values("split_index")[split_metric].to_numpy())
                primary = float(tls_patient[(tls_patient.coefficient_set == coef) & (tls_patient.heldout_patient == p) & (tls_patient.method == row)]
                                [patient_metric].iloc[0])
            primaries.append(primary)
            xs = pj + np.linspace(0.08, 0.92, len(raw))
            ys = ri + 0.86 - norm(raw) * 0.72
            # Sparse reference marks remain below the split points and primary tick.
            reference_y = ri + .86 - norm(0 if norm is STATE_NORM else .5) * .72
            ax.plot([pj + .04, pj + .96], [reference_y, reference_y], color=GRID, lw=.32, zorder=1)
            points = ax.scatter(xs, ys, s=3.2, c=raw, cmap=cmap, norm=norm, alpha=0.86, linewidths=0, zorder=2)
            split_artists.append((points, raw.copy(), norm, ri))
            py = ri + 0.86 - norm(primary) * 0.72
            line, = ax.plot([pj + 0.34, pj + 0.66], [py, py], color=INK, lw=0.52,
                            solid_capstyle='butt', zorder=4)
            primary_artists.append((line, primary, norm, ri))
        # attached patient-equal mean rail
        mean = float(np.mean(primaries))
        my = ri + 0.86 - norm(mean) * 0.72
        ax.add_patch(Rectangle((8.20, ri + 0.08), 0.62, 0.84, facecolor="#F3F3F3", edgecolor="white", linewidth=0.5))
        ax.plot([8.30, 8.72], [my, my], color=RNA if row == "Measured RNA" else INK, lw=1.45)

    ax.set_xlim(-1.72 if show_methods else 0, 10.65)
    ax.set_ylim(nrows + 0.03, -0.78)
    ax.set_xticks([])
    ax.set_yticks([])
    ax.set_title(title, loc="left", pad=4, fontweight="bold")
    for s in ax.spines.values():
        s.set_visible(False)
    return ax


