# compact continuous scales under the two endpoint columns
def add_scale(pos, norm, cmap, ticks, label):
    ax = fig.add_axes(pos)
    grad = np.linspace(norm.vmin, norm.vmax, 256)[None, :]
    ax.imshow(grad, aspect="auto", cmap=cmap, norm=norm, extent=(norm.vmin, norm.vmax, 0, 1))
    ax.set_yticks([])
    ax.set_xticks(ticks)
    ax.set_xlabel(label, labelpad=1)
    for s in ax.spines.values():
        s.set_visible(False)

add_scale([0.27, 0.30560, 0.18, 0.01535], STATE_NORM, STATE_CMAP, [-0.25, 0, 0.3, 0.6], "Correlation")
add_scale([0.75, 0.30560, 0.18, 0.01535], AUC_NORM, AUC_CMAP, [0.2, 0.5, 0.9], "AUC")

