texts = list(fig.texts)
for axis in fig.axes:
    texts += list(axis.texts) + [axis.title, axis._left_title, axis._right_title]
    if axis.axison:
        texts += list(axis.get_xticklabels()) + list(axis.get_yticklabels()) + [axis.xaxis.label, axis.yaxis.label]
    if axis.get_legend():
        texts += list(axis.get_legend().get_texts())
for legend in fig.legends:
    texts += list(legend.get_texts())
texts = [t for t in texts if t.get_visible() and t.get_text()]
assert min(t.get_fontsize() for t in texts) >= 7.0
for text in texts:
    text.set_zorder(20)
fig.set_dpi(300)
fig.canvas.draw()
renderer = fig.canvas.get_renderer()
failures = []
for t in texts:
    bb = t.get_window_extent(renderer)
    if bb.x0 < 0 or bb.y0 < 0 or bb.x1 > fig.bbox.width or bb.y1 > fig.bbox.height:
        failures.append('clipped: ' + t.get_text())
for i, t in enumerate(texts):
    for u in texts[i + 1:]:
        if t.get_window_extent(renderer).overlaps(u.get_window_extent(renderer)):
            failures.append(f'text overlap: {t.get_text()} / {u.get_text()}')
assert len(split_artists) == 384 and sum(len(raw) for _, raw, _, _ in split_artists) == 7680
assert len(primary_artists) == 384
for points, raw, norm, row in split_artists:
    assert raw.min() >= norm.vmin and raw.max() <= norm.vmax
    assert np.allclose(points.get_offsets()[:, 1], row + .86 - norm(raw) * .72)
for line, value, norm, row in primary_artists:
    assert norm.vmin <= value <= norm.vmax
    assert np.allclose(line.get_ydata(), row + .86 - norm(value) * .72)
    assert np.isclose(line.get_xdata()[1] - line.get_xdata()[0], .32)
fig.savefig(PDF_OUT, dpi=300)
fig.savefig(PNG_OUT, dpi=300)
assert not failures, '\n'.join(failures)
